.cs-splash-button {
  position: fixed;
  bottom: 18px;
  right: 18px;
  z-index: 1100;
  background: linear-gradient(135deg, #38bdf8, #6366f1);
  color: white;
  border: none;
  border-radius: 12px;
  padding: 10px 14px;
  font-weight: 700;
  box-shadow: 0 12px 24px rgba(99, 102, 241, 0.35);
  cursor: pointer;
}
.cs-splash-overlay {
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at 20% 20%, rgba(56, 189, 248, 0.12), transparent 35%),
              radial-gradient(circle at 80% 20%, rgba(99, 102, 241, 0.12), transparent 35%),
              rgba(15, 23, 42, 0.8);
  backdrop-filter: blur(6px);
  display: grid;
  place-items: center;
  z-index: 1099;
  opacity: 0;
  pointer-events: none;
  transition: opacity 160ms ease;
}
.cs-splash-overlay[data-open="true"] {
  opacity: 1;
  pointer-events: auto;
}
.cs-splash-panel {
  width: min(960px, 90vw);
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  padding: 18px;
  color: white;
  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.35);
}
.cs-splash-close {
  border: 1px solid rgba(255, 255, 255, 0.3);
  background: rgba(255, 255, 255, 0.08);
  color: white;
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  float: right;
  cursor: pointer;
}
.cs-splash-greeting {
  font-weight: 700;
  letter-spacing: 0.02em;
  margin-bottom: 12px;
}
.cs-splash-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 12px;
}
.cs-splash-card {
  padding: 14px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.07);
}
.cs-splash-title {
  font-weight: 700;
  margin-bottom: 6px;
}
.cs-splash-metric {
  font-size: 1.8rem;
  font-weight: 800;
}
.cs-splash-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(56, 189, 248, 0.18);
  border: 1px solid rgba(56, 189, 248, 0.4);
  font-size: 0.85rem;
  margin-right: 6px;
  margin-top: 6px;
}
.cs-splash-actions {
  margin-top: 8px;
}

