(function() {
  'use strict';
  if (window.__CS_SPLASH_DASHBOARD__) return;
  window.__CS_SPLASH_DASHBOARD__ = true;

  const api = window.CardSpoke?.utils;
  const inspirations = [
    'Build boldly today.',
    'Momentum loves clarity.',
    'Great cards become great outcomes.',
    'Keep your ideas flowing.',
    'Small wins power big leaps.'
  ];

  const countCards = () => document.querySelectorAll('.card, .card-detail').length;
  const countTags = () => new Set(Array.from(document.querySelectorAll('.tag, .card-tag')).map((t) => t.textContent?.trim()).filter(Boolean)).size;
  const today = () => new Intl.DateTimeFormat('en', { weekday: 'long', month: 'short', day: 'numeric' }).format(new Date());

  const toggleSplash = () => {
    const overlay = buildSplash();
    const isOpen = overlay.dataset.open === 'true';
    overlay.dataset.open = (!isOpen).toString();
  };

  const createButton = () => {
    let btn = document.querySelector('.cs-splash-button');
    if (btn) return btn;
    btn = document.createElement('button');
    btn.className = 'cs-splash-button';
    btn.textContent = 'Open Dashboard';
    btn.addEventListener('click', toggleSplash);
    document.body.appendChild(btn);
    return btn;
  };

  const buildCard = (title, content, pills = []) => {
    const card = document.createElement('div');
    card.className = 'cs-splash-card';
    const h = document.createElement('div');
    h.className = 'cs-splash-title';
    h.textContent = title;
    const body = document.createElement('div');
    body.innerHTML = content;
    card.appendChild(h);
    card.appendChild(body);
    if (pills.length) {
      const wrap = document.createElement('div');
      wrap.className = 'cs-splash-actions';
      pills.forEach((pill) => {
        const span = document.createElement('span');
        span.className = 'cs-splash-pill';
        span.textContent = pill;
        wrap.appendChild(span);
      });
      card.appendChild(wrap);
    }
    return card;
  };

  const buildSplash = () => {
    let overlay = document.querySelector('.cs-splash-overlay');
    if (overlay) return overlay;
    overlay = document.createElement('div');
    overlay.className = 'cs-splash-overlay';

    const panel = document.createElement('div');
    panel.className = 'cs-splash-panel';

    const close = document.createElement('button');
    close.className = 'cs-splash-close';
    close.textContent = '✕';
    close.addEventListener('click', toggleSplash);

    const greeting = document.createElement('div');
    greeting.className = 'cs-splash-greeting';
    greeting.textContent = `${today()} • ${inspirations[Math.floor(Math.random() * inspirations.length)]}`;

    const grid = document.createElement('div');
    grid.className = 'cs-splash-grid';

    grid.appendChild(buildCard('Your Boards', `<div class="cs-splash-metric">${countCards()}</div><div>cards spotted in view</div>`, ['Try: Cmd/Ctrl + K', 'Focus mode? Shift + Z']));
    grid.appendChild(buildCard('Tags & Topics', `<div class="cs-splash-metric">${countTags()}</div><div>unique tags detected</div>`, ['Tidy tags weekly', 'Pin favorites']));
    grid.appendChild(buildCard('Quick Actions', '<ul><li>Create a new card with N</li><li>Search instantly with /</li><li>Re-center with R</li></ul>', ['Speedrun your board']));
    grid.appendChild(buildCard('Mood Boost', '<div>Play your soundtrack, hydrate, and share wins.</div>', ['Celebrate progress']));

    panel.appendChild(close);
    panel.appendChild(greeting);
    panel.appendChild(grid);

    overlay.appendChild(panel);
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) toggleSplash();
    });

    document.body.appendChild(overlay);
    return overlay;
  };

  const observer = new MutationObserver(() => {
    const overlay = document.querySelector('.cs-splash-overlay');
    if (!overlay) return;
    const metric = overlay.querySelector('.cs-splash-metric');
    if (metric) metric.textContent = countCards();
  });

  const enable = () => {
    createButton();
    buildSplash();
    observer.observe(document.body, { childList: true, subtree: true });
    api?.showToast?.('Splash Dashboard installed — click Open Dashboard to launch.', 'info');
  };

  const disable = () => {
    observer.disconnect();
    document.querySelectorAll('.cs-splash-overlay, .cs-splash-button').forEach((el) => el.remove());
  };

  if (window.CardSpoke_MODS?.register) {
    CardSpoke_MODS.register('plugin-splash-dashboard', {
      meta: { name: 'Splash Dashboard', type: 'Plugin', version: '1.1.0' },
      onAppInit: enable,
      onCardRender() { const overlay = document.querySelector('.cs-splash-overlay[data-open="true"]'); if (overlay) overlay.dataset.open = 'true'; },
      onDisable: disable,
      onUninstall: disable
    });
  } else {
    enable();
  }
})();
